def build_prompt(question, mode, effort=75):
    msgs = [{"role": "user", "content": question}]
    if mode == "thinking":
        return encode_messages(msgs, thinking_mode="thinking", reasoning_effort=effort)
    return encode_messages(msgs, thinking_mode="chat")

