def complete(base, prompt, max_tokens=512, timeout=600, temperature=0.0):
    if not SERIALIZE_PREFILL:
        body = {"model": EVAL_MODEL, "prompt": prompt, "max_tokens": max_tokens,
                "temperature": temperature}
        req = urllib.request.Request(base.rstrip("/") + "/v1/completions",
                                     data=json.dumps(body).encode(),
                                     headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read())["choices"][0]["text"]
    # streaming + global prefill gate: hold the lock only through first content token
    body = {"model": EVAL_MODEL, "prompt": prompt, "max_tokens": max_tokens,
            "temperature": temperature, "stream": True,
            "stream_options": {"include_usage": True}}
    req = urllib.request.Request(base.rstrip("/") + "/v1/completions",
                                 data=json.dumps(body).encode(),
                                 headers={"Content-Type": "application/json"})
    parts = []
    got_first = False
    r = None
    with PREFILL_LOCK:
        r = urllib.request.urlopen(req, timeout=timeout)
        try:
            for raw in r:
                line = raw.decode("utf-8", "ignore").strip()
                if not line.startswith("data:"):
                    continue
                data = line[5:].strip()
                if data == "[DONE]":
                    return "".join(parts)
                try:
                    obj = json.loads(data)
                except Exception:
                    continue
                text = ((obj.get("choices") or [{}])[0].get("text") or "")
                if text:
                    parts.append(text)
                    got_first = True
                    break
        finally:
            if r is not None and not got_first:
                r.close()
    if not got_first or r is None:
        return "".join(parts)
    try:
        for raw in r:
            line = raw.decode("utf-8", "ignore").strip()
            if not line.startswith("data:"):
                continue
            data = line[5:].strip()
            if data == "[DONE]":
                break
            try:
                obj = json.loads(data)
            except Exception:
                continue
            text = ((obj.get("choices") or [{}])[0].get("text") or "")
            if text:
                parts.append(text)
    finally:
        r.close()
    return "".join(parts)

extract_gsm8k.source:
def extract_gsm8k(text):
    if not text:
        return ""
    m = re.findall(r"####\s*([^\n]+)", text)
    if m:
        nums = NUM.findall(m[-1].replace(",", "").replace("$", ""))
        if nums:
            return nums[-1].rstrip(".")
    nums = NUM.findall(text.replace(",", "").replace("$", ""))
    return nums[-1].rstrip(".") if nums else ""

